CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE TABLE IF NOT EXISTS hs_codes_china(hs_code_8 VARCHAR(8) PRIMARY KEY,hs_code VARCHAR(13),hs_code_10 VARCHAR(10),chapter VARCHAR(2) NOT NULL,section VARCHAR(5),description_en TEXT NOT NULL,description_zh TEXT NOT NULL,mfn_duty_rate DECIMAL(6,2),vat_rate DECIMAL(6,2),requires_licence BOOLEAN DEFAULT FALSE,ciq_inspection BOOLEAN DEFAULT FALSE,is_restricted BOOLEAN DEFAULT FALSE,is_prohibited BOOLEAN DEFAULT FALSE,supervisory_conditions TEXT,ciq_codes VARCHAR(50),data_source TEXT,last_updated TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS hs_codes_india(hs_code VARCHAR(8) PRIMARY KEY,chapter VARCHAR(2) NOT NULL,section VARCHAR(5),description_en TEXT NOT NULL,description_hi TEXT,bcd_rate DECIMAL(6,2),igst_rate DECIMAL(6,2),sws_rate DECIMAL(6,2) DEFAULT 10,import_policy TEXT,requires_licence BOOLEAN DEFAULT FALSE,requires_inspection BOOLEAN DEFAULT FALSE,inspection_agency TEXT,is_restricted BOOLEAN DEFAULT FALSE,is_prohibited BOOLEAN DEFAULT FALSE,data_source TEXT,last_updated TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS bilateral_mappings(id SERIAL PRIMARY KEY,china_hs_code_8 VARCHAR(8) REFERENCES hs_codes_china,india_hs_code VARCHAR(8) REFERENCES hs_codes_india,match_confidence DECIMAL(4,3),match_method TEXT,UNIQUE(china_hs_code_8,india_hs_code));
CREATE TABLE IF NOT EXISTS synonyms(id SERIAL PRIMARY KEY,term TEXT UNIQUE,canonical TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS exchange_rates(id SERIAL PRIMARY KEY,from_currency VARCHAR(3),to_currency VARCHAR(3),rate DECIMAL(12,4),effective_date DATE,source TEXT,updated_by TEXT,created_at TIMESTAMPTZ DEFAULT NOW(),UNIQUE(from_currency,to_currency));
CREATE TABLE IF NOT EXISTS search_logs(id SERIAL PRIMARY KEY,query TEXT,country TEXT,result_count INT,language TEXT,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS ai_classifications(id SERIAL PRIMARY KEY,product_description TEXT,language TEXT,country TEXT,results JSONB,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS error_logs(id SERIAL PRIMARY KEY,route TEXT,message TEXT,stack TEXT,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE INDEX IF NOT EXISTS china_desc_trgm ON hs_codes_china USING gin(description_en gin_trgm_ops); CREATE INDEX IF NOT EXISTS india_desc_trgm ON hs_codes_india USING gin(description_en gin_trgm_ops);
CREATE OR REPLACE VIEW daily_metrics AS SELECT date_trunc('day',created_at) AS metric_day,count(*) AS searches,jsonb_agg(query) AS queries FROM search_logs GROUP BY 1;
